import { Routes, Route, Link } from 'react-router-dom';
import AboutPage from './Paginas/AboutPage';



function HomePage() {
  const navigate = useNavigate();

  function goToAboutPage() {
    navigate('/about');
  }

  return (
    <div>
      <h1>My First React Project</h1>
      <p>This is the Home Page. Welcome!</p>

      <button onClick={goToAboutPage}>
        Go to About Page with a Button
      </button>
    </div>
  );
}

function App() {
  return (
    <div>
      {/* 1. This is our navigation menu. It will appear on all pages. */}
      <nav>
        <Link to="/home">Home</Link> | <Link to="/about">About</Link>
      </nav>

      <hr /> {/* A horizontal line to separate nav from content */}

      {/* 2. This is where the page content will be swapped out */}
      <Routes>
        <Route path="/" element={<HomePage/>} />
        <Route path="/about" element={<AboutPage/>} />
      </Routes>
    </div>
  );
}

export default App;
